  x=pd.read_csv(f); x['date']=pd.to_datetime(x.date); x=x.sort_values('date')
  x['gap']=x.open/x.close.shift(1)-1
  # signal known at prior close: previous day's gap, predict next close-to-close return
  x['sig']= -x.gap
  x['fwd']=x.close.shift(-1)/x.close-1
  D[s]=x[['date','sig','fwd']]
