from scipy.stats import spearmanr
cut=pd.Timestamp('2027-03-24')
assets=sorted(os.path.basename(x)[:-4] for x in glob.glob('../persistent/stock_data/*.csv'))
px={}; rr={}
for a in assets:
 d=pd.read_csv('../persistent/stock_data/'+a+'.csv',parse_dates=['date']).sort_values('date').set_index('date'); d=d[d.index<=cut]; px[a]=d.close; rr[a]=d.close.pct_change()
p=pd.DataFrame(px).sort_index(); r=pd.DataFrame(rr).sort_index(); market=r.median(axis=1)
# Novel orthogonal signal: 5d idiosyncratic momentum, attenuated when US-CN yield spread makes an extreme move.
sp=np.log(p['US10Y'].clip(lower=1e-9))-np.log(p['CN10Y'].clip(lower=1e-9)); sh=sp.diff(5); med=sh.rolling(120,min_periods=60).median(); mad=(sh-med).abs().rolling(120,min_periods=60).median(); stress=((sh-med)/(mad+1e-6)).clip(-3,3).abs().reindex(r.index).fillna(0)
F={}
for a in assets:
 beta=r[a].rolling(60,min_periods=30).cov(market)/market.rolling(60,min_periods=30).var(); resid=r[a]-beta*market
 mom=resid.rolling(5,min_periods=5).sum()
 F[a]=(mom/(1+0.35*stress)).clip(-.2,.2)
fac=pd.DataFrame(F).sort_index(); fac.to_csv('scripts/miner_2_20270325_rate_conditioned_resid_momentum_signal.csv')
print('assets',len(assets),'rows',len(fac),'period',fac.index.min(),fac.index.max())
for h in [1,5,10]:
 fw=p.pct_change(h).shift(-h); vals=[]; ns=[]; ds=[]
 for dt in fac.index:
